  const domainNames = {
    ai:"الذكاء الاصطناعي", data:"تحليل وهندسة البيانات", cyber:"الأمن السيبراني",
    software:"تطوير البرمجيات", ux:"تجربة المستخدم", business:"ريادة الأعمال", general:"المهارات الجامعية"
  };
  // Input lengths are bounded to keep inference predictable on student devices.
  function terms(text) {
    const normalized = String(text || "").slice(0,1200).normalize("NFKC").toLowerCase()
      .replace(/[\u064B-\u065F\u0670\u0640]/g,"").replace(/[أإآٱ]/g,"ا").replace(/ى/g,"ي").replace(/ة/g,"ه");
    const words = normalized.match(/[a-z0-9\u0621-\u063A\u0641-\u064A\u0660-\u0669]+/g) || [];
    const counts = new Map();
    function add(term,n=1) { counts.set(term,(counts.get(term)||0)+n); }
    for (const w of words) {
      add("@"+w,2);
      const padded="^"+w+"$";
      for(const length of [2,3,4])
        for(let i=0;i+length<=padded.length;i++) add(padded.slice(i,i+length));
    }
    return counts;
  }
  // The exported coefficients use signed int8 per head, including their fitted scale.
  for(const head of Object.values(models)) {
    head.index = new Map(head.vocabulary.map((v,i)=>[v,i]));
    const raw = atob(head.weights);
    head.coefficients = Int8Array.from(raw, ch=>ch.charCodeAt(0));
  }
  function classify(head, features) {
    const indices=[], values=[];
    let norm=0;
    for (const [key,count] of features) {
      const i=head.index.get(key); if(i===undefined) continue;
      const w=(1+Math.log(count))*head.idf[i];
      indices.push(i); values.push(w); norm+=w*w;
    }
    norm=Math.sqrt(norm)||1;
    const logits=head.labels.map((label,c)=>{
      let numerator=0;
      const base=c*head.vocabulary.length;
      for(let i=0;i<indices.length;i++) numerator+=head.coefficients[base+indices[i]]*values[i];
      return head.offsets[c]+head.scale*numerator/norm;
    });
    const max=Math.max(...logits);
    const weights=logits.map(x=>Math.exp(x-max));
    const total=weights.reduce((a,b)=>a+b,0);
    return head.labels.map((id,i)=>({id,label:domainNames[id]||id,score:weights[i]/total}))
      .sort((a,b)=>b.score-a.score);
  }
  const supported = ranks=>ranks[0].score>=.32 && ranks[0].score-ranks[1].score>=.09;
  function domainSignals(text,features) {
    const ranks=classify(models.domain,features);
    // A two-topic request can contain separate strong signals despite tied logits for the entire request.
    const pieces=text.split(/[,،;؛+&]|\s+and\s+|\s+و(?=(?:ال|تعل|تصم|رياد|حما|تطو|تحل|برم|هندس))/i)
      .map(v=>v.trim()).filter(v=>v.length>=4).slice(0,4);
    const detected = new Map();
    if(supported(ranks) && ranks[0].id!=="unknown") detected.set(ranks[0].id,ranks[0]);
    if(pieces.length>1) for(const piece of pieces) {
      const d=classify(models.domain,terms(piece));
      if(supported(d) && d[0].id!=="unknown" && d[0].score>=.48) {
        const prev=detected.get(d[0].id);
        if(!prev || d[0].score>prev.score)detected.set(d[0].id,d[0]);
      }
    }
    return [...detected.values()].sort((a,b)=>b.score-a.score).slice(0,3);
  }
  function infer(input) {
    const text=String(input||"").trim().slice(0,1200), features=terms(text);
    const ranks=classify(models.intent,features);
    const intent=supported(ranks)?ranks[0].id:"unknown";
    return {intent,confidence:ranks[0].score,domains:domainSignals(text,features)};
  }
  // Disciplines are inferred from actual catalog names/descriptions, not course code conditions.
  const signals=new Map();
  function courseSignals(c) {
    const sample=c.name+" "+c.description;
    if(!signals.has(sample)) signals.set(sample,classify(models.domain,terms(sample)));
    return signals.get(sample);
  }
  function recommend(input,profile=window.Madar.getProfile()) {
    const m=window.Madar;
    const {domains}=infer(input);
    if(!domains.length) return {recognized:false,domains:[],items:[]};
    const catalog=m.courses;
    const direct=new Map();
    for(const c of catalog) {
      const signals=courseSignals(c);
      // Multiple goals receive proportional weights without inferring user grades or sensitive traits.
      let value=0, matched=domains[0];
      for(const d of domains) {
        const relevance=signals.find(s=>s.id===d.id).score * Math.sqrt(d.score/domains[0].score);
        if(relevance>value){value=relevance;matched=d;}
      }
      direct.set(c.code,{value,matched});
    }
    const routes=new Map(catalog.map(c=>[c.code,{...direct.get(c.code),via:null,distance:0}]));
    // Propagate learned destination relevance to prerequisite steps, furthest semester first.
    for(const c of [...catalog].sort((a,b)=>b.term-a.term)){
      const destination=routes.get(c.code);
      for(const p of c.prereqs){
        const prev=routes.get(p);
        if(prev && destination.value*.76>prev.value){
          routes.set(p,{value:destination.value*.76,matched:destination.matched,via:c,distance:destination.distance+1});
        }
      }
    }
    const items=[];
    for(const c of catalog){
      const status=m.status(c.code,profile);
      if(status==="completed") continue;
      const match=routes.get(c.code);
      if(match.value<.29)continue;
      const offered=c.sections.length>0;
      const availableSections=status==="eligible"?c.sections.filter(s=>m.preview("add",c.code,s.id,profile).ok):[];
      const actionable=availableSections.length>0;
      const boost=actionable?.13:status==="registered"?.05:0;
      const reason=match.via
        ?"يمهّد لدراسة «"+match.via.name+"» ضمن المسار المؤدي إلى "+match.matched.label+"."
        :"يرتبط توصيف المقرر بهدفك في "+match.matched.label+". "+c.description;
      items.push({course:c,score:Math.min(1,match.value*.86+boost),reason,status,offered,
        actionable,availableSections,domain:match.matched.id,via:match.via?.code||null});
    }
    items.sort((a,b)=>b.score-a.score || a.course.term-b.course.term || a.course.code.localeCompare(b.course.code));
    // Include one next step for this profile alongside future destination courses.
    const selected=items.slice(0,5);
    if(!selected.some(x=>x.actionable||x.status==="registered")){
      const next=items.find(x=>x.actionable||x.status==="registered");
      if(next){ selected.pop();selected.push(next); }
    }
    return {recognized:true,domains,items:selected};
  }
  window.MadarML={infer,recommend,info:{version:"1.0",algorithm:"TF-IDF / multinomial logistic regression",
    intentExamples:models.intent.size,domainExamples:models.domain.size,labels:domainNames}};
